const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=(v='')=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmt=(v)=>v?new Date(v).toLocaleString('th-TH',{dateStyle:'short',timeStyle:'short'}):'-';
const dateInput=(v)=>{if(!v)return'';const d=new Date(v);const z=new Date(d.getTime()-d.getTimezoneOffset()*60000);return z.toISOString().slice(0,16)};
const asArr=v=>Array.isArray(v)?v:[];
function toast(msg,type='info'){const t=$('#toast');if(!t)return;t.textContent=msg;t.style.background=type==='bad'?'#b42318':type==='ok'?'#067647':'#101828';t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
function setSession(s){state.session=s||null;if(s)localStorage.setItem(SK,JSON.stringify(s));else localStorage.removeItem(SK)}
function addTrace(x){state.trace.unshift({...x,time:new Date().toISOString()});state.trace=state.trace.slice(0,100)}
function errText(e){return e?.message||String(e||'UNKNOWN_ERROR')}
async function request(url,opts={},allowRefresh=true){
  const start=performance.now(); const method=opts.method||'GET';
  const headers={apikey:CONFIG.publishableKey,...(opts.headers||{})};
  if(state.session?.access_token) headers.Authorization=`Bearer ${state.session.access_token}`;
  let res;
  try{res=await fetch(url,{...opts,headers});}
  catch(e){addTrace({method,url,status:'NETWORK',ok:false,ms:Math.round(performance.now()-start),error:errText(e)});throw e}
  if(res.status===401&&allowRefresh&&state.session?.refresh_token){
    const ok=await refreshSession(); if(ok)return request(url,opts,false);
  }
  const raw=await res.text(); let data=null;try{data=raw?JSON.parse(raw):null}catch{data=raw}
  const tr={method,url,status:res.status,ok:res.ok,ms:Math.round(performance.now()-start),error:res.ok?'':(data?.message||data?.error||raw||res.statusText)};addTrace(tr);
  if(!res.ok){const e=new Error(tr.error||`HTTP ${res.status}`);e.status=res.status;e.data=data;throw e}
  return data;
}
async function rpc(name,args={}){return request(`${CONFIG.supabaseUrl}/rest/v1/rpc/${name}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(args)})}
async function edge(name,args={},auth=true){const h={'Content-Type':'application/json'};if(!auth)delete h.Authorization;return request(`${CONFIG.supabaseUrl}/functions/v1/${name}`,{method:'POST',headers:h,body:JSON.stringify(args)},auth)}
async function refreshSession(){
  if(!state.session?.refresh_token)return false;
  try{const d=await request(`${CONFIG.supabaseUrl}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh_token:state.session.refresh_token})},false);setSession(d);return !!d?.access_token}catch{setSession(null);state.profile=null;return false}
}
async function logout(){try{if(state.session)await request(`${CONFIG.supabaseUrl}/auth/v1/logout`,{method:'POST'},false)}catch{}setSession(null);state.profile=null;renderLogin()}
async function login(identifier,password){
  const start=performance.now();let res;
  try{res=await fetch(`${CONFIG.supabaseUrl}/functions/v1/clean-login`,{method:'POST',headers:{apikey:CONFIG.publishableKey,'Content-Type':'application/json'},body:JSON.stringify({identifier,password})});
    const data=await res.json().catch(()=>({}));addTrace({method:'POST',url:'/functions/v1/clean-login',status:res.status,ok:res.ok,ms:Math.round(performance.now()-start),error:res.ok?'':data.error});
    if(!res.ok)throw new Error(data.error||'เข้าสู่ระบบไม่สำเร็จ');setSession(data.session);state.profile=data.profile;state.route='dashboard';if(isPhone()){await renderMobileAfterLogin()}else{renderShell();await navigate('dashboard')}
  }catch(e){throw e}
}
function isPhone(){return innerWidth<CONFIG.minWidth}
function clearMobileQuery(){const u=new URL(location.href);u.searchParams.delete('att');u.searchParams.delete('mode');history.replaceState(null,'',u.pathname+u.search+u.hash)}
async function renderPublicProfileToken(token){
  try{const d=await rpc('clean_public_profile_by_qr',{p_token:token});const p=d.profile||{};document.body.innerHTML=`<div class="public-profile"><div class="public-card"><div class="brand-mark big">NR</div><h1>${esc(p.full_name||'ไม่พบข้อมูล')}</h1><div class="student-code">${esc(p.student_code||'-')}</div><div class="profile-list"><div><span>ห้องเรียน</span><strong>${esc(p.classroom_name||'-')}</strong></div><div><span>ปี/ภาคเรียน</span><strong>${esc(p.academic_year||'-')} / ${esc(p.semester||'-')}</strong></div><div><span>สถานะ</span><strong>${p.active?'กำลังใช้งาน':'ไม่ใช้งาน'}</strong></div></div><p class="muted">DOC-FULL-NR • QR ประจำตัวนักศึกษา</p></div></div>`}
  catch(e){document.body.innerHTML=`<div class="phone-block"><div class="box"><h1>QR ไม่ถูกต้อง</h1><p>${esc(errText(e))}</p></div></div>`}
}
async function renderMobileAfterLogin(){
  if(state.profile?.role!=='student'){renderMobileStaffNotice();return}
  renderMobileShell();
  const u=new URL(location.href);const token=u.searchParams.get('att');const mode=u.searchParams.get('mode');
  if(token){await processAttendanceToken(token,mode||'auto',true)}
}
async function boot(){
  try{state.build=await fetch('./BUILD.json',{cache:'no-store'}).then(r=>r.json())}catch{}
  const pubToken=new URL(location.href).searchParams.get('profile');if(pubToken){await renderPublicProfileToken(pubToken);return}
  try{const s=JSON.parse(localStorage.getItem(SK)||'null');if(s?.access_token)setSession(s)}catch{}
  if(!state.session){renderLogin();return}
  try{
    await rpc('clean_health');state.profile=await rpc('clean_my_profile');if(!state.profile?.id)throw new Error('PROFILE_NOT_FOUND');
    if(isPhone())await renderMobileAfterLogin();else{renderShell();await navigate(location.hash.replace('#/','')||'dashboard')}
  }catch{
    if(await refreshSession()){try{state.profile=await rpc('clean_my_profile');if(isPhone())await renderMobileAfterLogin();else{renderShell();await navigate('dashboard')}return}catch{}}
    renderLogin()
  }
}
function renderLogin(){document.body.innerHTML=`<div id="app"></div><div id="toast" class="toast"></div>`;$('#app').innerHTML=`
  <div class="login-shell"><section class="login-hero"><span class="badge">CLEAN REBUILD • Semester 2/2569</span><h1>DOC-FULL-NR<br>ระบบงานการเรียนการสอน</h1><p>ระบบหลักสำหรับ Desktop/Tablet และ Mobile Companion สำหรับส่งงานย้อนหลังกับ QR เช็กชื่อ โดยไม่ใช้ Mobile/PWA runtime รุ่นเก่า</p></section>
  <section class="login-panel"><form id="loginForm" class="login-card"><h2>เข้าสู่ระบบ</h2><div class="sub">ใช้ Username, รหัสนักศึกษา หรือ Email</div><div class="field"><label>บัญชีผู้ใช้</label><input name="identifier" autocomplete="username" required></div><div class="field"><label>รหัสผ่าน</label><input name="password" type="password" autocomplete="current-password" required></div><button class="btn primary full" type="submit">เข้าสู่ระบบ</button><div id="loginError"></div><div class="notice">Build: ${esc(CONFIG.build)} • ภาคเรียน 2/2569</div></form></section></div>`;
  $('#loginForm').onsubmit=async e=>{e.preventDefault();const b=$('#loginForm button');b.disabled=true;b.textContent='กำลังเข้าสู่ระบบ...';$('#loginError').innerHTML='';try{await login(e.target.identifier.value,e.target.password.value)}catch(x){$('#loginError').innerHTML=`<div class="error">${esc(errText(x))}</div>`}finally{b.disabled=false;b.textContent='เข้าสู่ระบบ'}}
}
