pages.assignments=async()=>{const m=await rpc('clean_admin_master_data');const teachers=m.users.filter(x=>x.role==='teacher');setMain(head('มอบหมายครู','กำหนดครู → วิชา → ห้องเรียน',`<button class="btn primary" id="addAssign">+ มอบหมาย</button>`)+`<div class="table-wrap"><table class="table"><thead><tr><th>ครู</th><th>วิชา</th><th>ห้อง</th><th>สถานะ</th></tr></thead><tbody>${m.teacher_assignments.map(x=>`<tr><td>${esc(x.teacher_name)}</td><td>${esc(x.subject_code)} ${esc(x.subject_name)}</td><td>${esc(x.classroom_name)}</td><td>${statusPill(x.active?'active':'inactive')}</td></tr>`).join('')}</tbody></table></div>${teachers.length?'':'<div class="notice">ยังไม่มีบัญชี role=teacher สามารถสร้างได้จากเมนูผู้ใช้ ส่วน Admin สามารถจัดการทุกวิชาได้อยู่แล้ว</div>'}`);$('#addAssign').onclick=()=>modal('มอบหมายครู',`<div class="field"><label>ครู</label><select name="teacher">${opt(teachers,'id',x=>x.full_name)}</select></div><div class="field"><label>วิชา</label><select name="subject">${opt(m.subjects,'id',x=>`${x.code} ${x.name}`)}</select></div><div class="field"><label>ห้อง</label><select name="classroom">${opt(m.classrooms,'id',x=>x.name)}</select></div>`,async f=>{await rpc('clean_admin_set_teacher_assignment',{p_teacher_id:f.get('teacher'),p_subject_id:f.get('subject'),p_classroom_id:f.get('classroom'),p_active:true});toast('มอบหมายแล้ว','ok');navigate('assignments',false)})};
pages.attendance=async()=>{
  if(state.profile.role==='student'){const rows=await rpc('clean_my_attendance');setMain(head('ประวัติเช็กชื่อ','แสดงสถานะเช็กชื่อของคุณ')+`<div class="table-wrap"><table class="table"><thead><tr><th>วันที่</th><th>วิชา</th><th>ห้อง</th><th>สถานะ</th><th>หมายเหตุ</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.session_date)}</td><td>${esc(x.subject_code)} ${esc(x.subject_name)}</td><td>${esc(x.classroom_name)}</td><td>${statusPill(x.status)}</td><td>${esc(x.note||'-')}</td></tr>`).join('')}</tbody></table></div>`);return}
  const [scope,sessions]=await Promise.all([rpc('clean_staff_scope'),rpc('clean_attendance_sessions_list')]);setMain(head('เช็กชื่อ','เริ่ม Session → โหลดรายชื่อ → มา/สาย/ขาด/ลา → ปิด Session',`<button class="btn primary" id="startAtt">+ เริ่มเช็กชื่อ</button>`)+`<div class="table-wrap"><table class="table"><thead><tr><th>วันที่</th><th>วิชา</th><th>ห้อง</th><th>สถานะ</th><th>จำนวน</th><th></th></tr></thead><tbody>${sessions.map(x=>`<tr><td>${esc(x.session_date)}<div class="mini">${fmt(x.started_at)}</div></td><td>${esc(x.subject_code)} ${esc(x.subject_name)}</td><td>${esc(x.classroom_name)}</td><td>${statusPill(x.status)}</td><td>${x.roster_count}</td><td><button class="btn light sm" data-roster="${x.id}">เปิดรายชื่อ</button></td></tr>`).join('')}</tbody></table></div>`);$('#startAtt').onclick=()=>modal('เริ่มเช็กชื่อ',`<div class="field"><label>วิชา</label><select name="subject">${opt(scope.subjects,'id',x=>`${x.code} ${x.name}`)}</select></div><div class="field"><label>ห้องเรียน</label><select name="classroom">${opt(scope.classrooms,'id',x=>x.name)}</select></div><div class="field"><label>หมายเหตุ</label><input name="note"></div>`,async f=>{const d=await rpc('clean_attendance_start',{p_subject_id:f.get('subject'),p_classroom_id:f.get('classroom'),p_note:f.get('note')});toast(`สร้าง Session แล้ว ${d.roster_count} คน`,'ok');await showRoster(d.session_id)});$$('[data-roster]').forEach(b=>b.onclick=()=>showRoster(b.dataset.roster))
};
async function showRoster(id){const d=await rpc('clean_attendance_roster',{p_session_id:id});const s=d.session;setMain(head('รายชื่อเช็กชื่อ',`${s.status} • ${s.session_date}`,`<button class="btn light" id="backAtt">← กลับ</button>${s.status==='open'?'<button class="btn secondary" id="qrPresent">QR เข้าเรียน</button><button class="btn warn" id="qrLate">QR มาสาย</button><button class="btn primary" id="closeAtt">ปิด Session</button>':''}`)+`<div class="table-wrap"><table class="table"><thead><tr><th>เลขที่</th><th>นักศึกษา</th><th>สถานะ</th><th>เลือกสถานะ</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td>${r.seat_number??'-'}</td><td>${esc(r.student_code||'')} ${esc(r.full_name)}</td><td>${statusPill(r.status)}</td><td>${s.status==='open'?['present','late','absent','excused'].map(st=>`<button class="btn sm ${r.status===st?'primary':'light'}" data-mark="${r.student_id}" data-st="${st}">${({present:'มา',late:'สาย',absent:'ขาด',excused:'ลา'})[st]}</button>`).join(''):'-'}</td></tr>`).join('')}</tbody></table></div>`);$('#backAtt').onclick=()=>navigate('attendance');if($('#qrPresent'))$('#qrPresent').onclick=()=>showAttendanceQr(id,'present');if($('#qrLate'))$('#qrLate').onclick=()=>showAttendanceQr(id,'late');if($('#closeAtt'))$('#closeAtt').onclick=async()=>{const x=await rpc('clean_attendance_close',{p_session_id:id});toast(`ปิด Session แล้ว: มา ${x.summary.present} สาย ${x.summary.late} ขาด ${x.summary.absent} ลา ${x.summary.excused}`,'ok');navigate('attendance')};$$('[data-mark]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await rpc('clean_attendance_set_status',{p_session_id:id,p_student_id:b.dataset.mark,p_status:b.dataset.st,p_note:null});await showRoster(id)}catch(e){toast(errText(e),'bad')}})}
pages.worksheets=async()=>state.profile.role==='student'?studentWorksheets():staffWorksheets();
async function staffWorksheets(){const [scope,rows]=await Promise.all([rpc('clean_staff_scope'),rpc('clean_staff_worksheets')]);setMain(head('ใบงาน','Digital และ Paper Worksheet',`<button class="btn primary" id="newWs">+ สร้างใบงาน</button>`)+`<div class="table-wrap"><table class="table"><thead><tr><th>ใบงาน</th><th>วิชา/ห้อง</th><th>โหมด</th><th>สถานะ</th><th>มอบหมาย/ส่ง</th><th></th></tr></thead><tbody>${rows.map(w=>`<tr><td><strong>${esc(w.title)}</strong><div class="mini">${esc(w.instructions||'')}</div></td><td>${esc(w.subject_code)} ${esc(w.subject_name)}<div class="mini">${esc(w.classroom_name||'ทุกห้อง')}</div></td><td>${statusPill(w.mode)}</td><td>${statusPill(w.status)}<div class="mini">${fmt(w.open_at)} → ${fmt(w.due_at)}</div></td><td>${w.assigned_count} / ${w.submitted_count}</td><td class="nowrap">${w.status==='draft'?`<button class="btn primary sm" data-pubws="${w.id}">Publish</button>`:''}${w.mode==='paper'&&w.status==='published'?`<button class="btn light sm" data-paper="${w.id}">ลงคะแนน</button>`:''}${w.status==='published'||w.status==='closed'?`<button class="btn ${w.allow_mobile_copy?'ok':'light'} sm" data-mobilecopy="${w.id}" data-enabled="${w.allow_mobile_copy}">${w.allow_mobile_copy?'มือถือ: เปิด':'เปิดส่งย้อนหลังมือถือ'}</button>`:''}</td></tr>`).join('')}</tbody></table></div>`);$('#newWs').onclick=()=>worksheetModal(scope);$$('[data-pubws]').forEach(b=>b.onclick=()=>publishWs(b.dataset.pubws));$$('[data-paper]').forEach(b=>b.onclick=()=>paperRoster(b.dataset.paper));$$('[data-mobilecopy]').forEach(b=>b.onclick=()=>mobileCopySetting(b.dataset.mobilecopy,b.dataset.enabled==='true'))}
function worksheetModal(scope){modal('สร้างใบงาน',`<div class="form-grid"><div class="field"><label>วิชา</label><select name="subject">${opt(scope.subjects,'id',x=>`${x.code} ${x.name}`)}</select></div><div class="field"><label>ห้อง (เว้นว่าง = ทุกห้องในวิชา)</label><select name="classroom"><option value="">ทุกห้อง</option>${opt(scope.classrooms,'id',x=>x.name)}</select></div><div class="field span2"><label>ชื่อใบงาน</label><input name="title" required></div><div class="field"><label>โหมด</label><select name="mode"><option>digital</option><option>paper</option></select></div><div class="field"><label>จำนวนครั้งสูงสุด</label><input name="attempts" type="number" value="1" min="1"></div><div class="field span2"><label>คำสั่ง</label><textarea name="instructions"></textarea></div><div class="field span2"><label>Questions JSON</label><textarea name="questions" rows="8">[{"id":"q001","type":"short","prompt":"อธิบายคำตอบของคุณ","points":10}]</textarea></div></div>`,async f=>{await rpc('clean_worksheet_save',{p_id:null,p_subject_id:f.get('subject'),p_classroom_id:f.get('classroom')||null,p_title:f.get('title'),p_description:null,p_instructions:f.get('instructions'),p_mode:f.get('mode'),p_questions:JSON.parse(f.get('questions')||'[]'),p_open_at:null,p_due_at:null,p_allow_late:false,p_allow_resubmit:false,p_max_attempts:+f.get('attempts')});toast('สร้างใบงานแล้ว','ok');navigate('worksheets',false)})}
function publishWs(id){modal('Publish ใบงาน',`<div class="field"><label>เปิด</label><input name="open" type="datetime-local" value="${dateInput(new Date())}" required></div><div class="field"><label>กำหนดส่ง</label><input name="due" type="datetime-local" required></div>`,async f=>{const d=await rpc('clean_worksheet_publish',{p_worksheet_id:id,p_open_at:new Date(f.get('open')).toISOString(),p_due_at:new Date(f.get('due')).toISOString()});toast(`Publish แล้ว ${d.assigned_count} คน`,'ok');navigate('worksheets',false)},'Publish')}
async function studentWorksheets(){const rows=await rpc('clean_my_worksheets');setMain(head('ใบงานของฉัน','Digital: บันทึก/ส่งออนไลน์ • Paper: พิมพ์จากคอม/แท็บเล็ต')+`<div class="course-grid">${rows.map(w=>`<div class="course-card"><div class="code">${esc(w.subject_code)}</div><h3>${esc(w.title)}</h3><p class="muted">${esc(w.instructions||'')}</p><div class="course-meta">${statusPill(w.mode)} ${statusPill(w.submission_status||'ยังไม่ส่ง')}</div><div class="row" style="margin-top:12px">${w.mode==='digital'?`<button class="btn primary" data-do-ws="${w.id}">ทำใบงาน</button>`:`<button class="btn light" data-print-ws="${w.id}">พิมพ์ใบงาน</button>`}</div></div>`).join('')}</div>`);$$('[data-do-ws]').forEach(b=>b.onclick=()=>doWorksheet(rows.find(x=>x.id===b.dataset.doWs)));$$('[data-print-ws]').forEach(b=>b.onclick=()=>printWorksheet(rows.find(x=>x.id===b.dataset.printWs)))}
function renderQuestions(qs,answers={}){return asArr(qs).map((q,i)=>{const id=q.id||`q${i+1}`,prompt=q.prompt||q.text||`ข้อ ${i+1}`,type=q.type||'short',opts=asArr(q.options);let input;if(['mcq','truefalse','singleChoice'].includes(type)&&opts.length){input=opts.map((o,j)=>{const value=typeof o==='object'?(o.id??o.value??o.text):o;const text=typeof o==='object'?(o.text??o.label??value):o;return `<label class="choice"><input type="radio" name="ans_${esc(id)}" value="${esc(value)}" ${String(answers[id]??'')===String(value)?'checked':''}> <span>${esc(text)}</span></label>`}).join('')}else input=`<textarea class="answer-box" name="ans_${esc(id)}">${esc(answers[id]??'')}</textarea>`;return `<div class="question" data-qid="${esc(id)}"><h4>${i+1}. ${esc(prompt)}</h4>${input}</div>`}).join('')}
function collectAnswers(root=document){const out={};$$('.question',root).forEach(q=>{const id=q.dataset.qid;const checked=q.querySelector('input[type=radio]:checked');const ta=q.querySelector('textarea');out[id]=checked?checked.value:(ta?.value??'')});return out}
function doWorksheet(w){modal(`ใบงาน • ${w.title}`,`<div class="notice">${esc(w.subject_code)} • กำหนดส่ง ${fmt(w.due_at)}</div><div id="worksheetQuestions">${renderQuestions(w.questions)}</div>`,async()=>{const answers=collectAnswers($('#modalForm'));await rpc('clean_submission_save',{p_worksheet_id:w.id,p_answers:answers,p_submit:true});toast('ส่งใบงานแล้ว','ok');navigate('worksheets',false)},'ส่งใบงาน');const foot=$('.modal-foot');const save=document.createElement('button');save.type='button';save.className='btn light';save.textContent='บันทึกร่าง';save.onclick=async()=>{await rpc('clean_submission_save',{p_worksheet_id:w.id,p_answers:collectAnswers($('#modalForm')),p_submit:false});toast('บันทึกร่างแล้ว','ok')};foot.insertBefore(save,foot.lastElementChild)}
function printWorksheet(w){setMain(head('พิมพ์ใบงาน',w.subject_code,`<button class="btn light" id="backWs">← กลับ</button><button class="btn primary" id="printNow">พิมพ์</button>`)+`<div class="print-sheet"><h2>${esc(w.title)}</h2><p><strong>${esc(w.subject_code)} ${esc(w.subject_name)}</strong></p><p>${esc(w.instructions||'')}</p>${asArr(w.questions).map((q,i)=>`<div class="q"><strong>${i+1}. ${esc(q.prompt||q.text||'')}</strong><div style="height:60px;border-bottom:1px solid #ddd"></div></div>`).join('')}</div>`);$('#backWs').onclick=()=>navigate('worksheets');$('#printNow').onclick=()=>print()}
async function paperRoster(id){const rows=await rpc('clean_paper_roster',{p_worksheet_id:id});setMain(head('ลงคะแนนใบงานกระดาษ','กรอกคะแนนรายคน',`<button class="btn light" id="backPaper">← กลับ</button>`)+`<div class="table-wrap"><table class="table"><thead><tr><th>นักศึกษา</th><th>คะแนน</th><th>เต็ม</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.student_code||'')} ${esc(r.full_name)}</td><td>${r.score??'-'}</td><td>${r.max_score??'-'}</td><td><button class="btn primary sm" data-gradepaper="${r.student_id}">ลงคะแนน</button></td></tr>`).join('')}</tbody></table></div>`);$('#backPaper').onclick=()=>navigate('worksheets');$$('[data-gradepaper]').forEach(b=>b.onclick=()=>modal('ลงคะแนน',`<div class="field"><label>คะแนน</label><input name="score" type="number" step="0.01" required></div><div class="field"><label>คะแนนเต็ม</label><input name="max" type="number" value="10" step="0.01" required></div><div class="field"><label>ความเห็น</label><textarea name="comment"></textarea></div>`,async f=>{await rpc('clean_paper_grade',{p_worksheet_id:id,p_student_id:b.dataset.gradepaper,p_score:+f.get('score'),p_max_score:+f.get('max'),p_comment:f.get('comment')});toast('บันทึกคะแนนแล้ว','ok');paperRoster(id)}))}
pages.submissions=async()=>{const [rows,mobile]=await Promise.all([rpc('clean_staff_submission_queue'),rpc('clean_staff_mobile_copy_queue')]);setMain(head('ตรวจงาน','Submission Queue + งานย้อนหลังจากมือถือ')+`<div class="card"><h3 class="panel-title">งานปกติ</h3><div class="table-wrap"><table class="table"><thead><tr><th>นักศึกษา</th><th>ใบงาน</th><th>สถานะ</th><th>คะแนน</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.student_code||'')} ${esc(r.full_name)}</td><td>${esc(r.subject_code)} • ${esc(r.worksheet_title)}</td><td>${statusPill(r.status)}</td><td>${r.score??'-'} / ${r.max_score??'-'}</td><td><button class="btn primary sm" data-review="${r.id}">ตรวจ</button></td></tr>`).join('')}</tbody></table></div></div><div class="card" style="margin-top:16px"><h3 class="panel-title">งานย้อนหลังจากมือถือ</h3>${mobile.length?`<div class="table-wrap"><table class="table"><thead><tr><th>นักศึกษา</th><th>ใบงาน</th><th>ส่งเมื่อ</th><th>สถานะ</th><th></th></tr></thead><tbody>${mobile.map(r=>`<tr><td>${esc(r.student_code||'')} ${esc(r.full_name)}</td><td>${esc(r.subject_code)} • ${esc(r.worksheet_title)}<div class="mini">ครั้งที่ ${r.attempt_no}</div></td><td>${fmt(r.submitted_at)}</td><td>${statusPill(r.status)}</td><td><button class="btn light sm" data-mobile-review="${r.id}">ดูภาพ/ตรวจรับ</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">ยังไม่มีงานย้อนหลังจากมือถือ</div>'}</div>`);$$('[data-review]').forEach(b=>b.onclick=()=>reviewSubmission(b.dataset.review));$$('[data-mobile-review]').forEach(b=>b.onclick=()=>reviewMobileCopy(mobile.find(x=>x.id===b.dataset.mobileReview)))};
async function reviewSubmission(id){const d=await rpc('clean_submission_detail',{p_submission_id:id});modal(`ตรวจงาน • ${d.student.full_name}`,`<div class="notice">${esc(d.worksheet.title)}</div><pre class="trace">${esc(JSON.stringify(d.submission.answers,null,2))}</pre><div class="form-grid"><div class="field"><label>คะแนน</label><input name="score" type="number" step="0.01" value="${d.grade?.score??''}" required></div><div class="field"><label>เต็ม</label><input name="max" type="number" step="0.01" value="${d.grade?.max_score??10}" required></div><div class="field"><label>เกรด/ระดับ</label><input name="grade" value="${esc(d.grade?.grade||'')}"></div><div class="field"><label>ความเห็น</label><textarea name="comment">${esc(d.grade?.comment||'')}</textarea></div></div>`,async f=>{await rpc('clean_submission_grade',{p_submission_id:id,p_score:+f.get('score'),p_max_score:+f.get('max'),p_grade:f.get('grade'),p_comment:f.get('comment')});toast('ให้คะแนนแล้ว','ok');navigate('submissions',false)},'บันทึกคะแนน')}
pages.exams=async()=>state.profile.role==='student'?studentExams():staffExams();
async function staffExams(){const [scope,rows]=await Promise.all([rpc('clean_staff_scope'),rpc('clean_exam_dashboard')]);setMain(head('ข้อสอบ','สร้าง → Publish → นักศึกษาทำ → ตรวจคะแนน',`<button class="btn primary" id="newExam">+ สร้างข้อสอบ</button>`)+`<div class="table-wrap"><table class="table"><thead><tr><th>ข้อสอบ</th><th>วิชา</th><th>ชนิด</th><th>สถานะ</th><th>มอบหมาย/Attempt</th><th></th></tr></thead><tbody>${rows.map(e=>`<tr><td><strong>${esc(e.title)}</strong><div class="mini">${fmt(e.open_at)} → ${fmt(e.due_at)}</div></td><td>${esc(e.subject_code)} ${esc(e.subject_name)}</td><td>${statusPill(e.exam_type)}</td><td>${statusPill(e.status)}</td><td>${e.assigned_count} / ${e.attempt_count}</td><td>${e.status==='draft'?`<button class="btn primary sm" data-pubexam="${e.id}">Publish</button>`:''}<button class="btn light sm" data-attempts="${e.id}">Attempts</button></td></tr>`).join('')}</tbody></table></div>`);$('#newExam').onclick=()=>examModal(scope);$$('[data-pubexam]').forEach(b=>b.onclick=()=>publishExam(b.dataset.pubexam));$$('[data-attempts]').forEach(b=>b.onclick=()=>examAttempts(b.dataset.attempts))}
function examModal(scope){modal('สร้างข้อสอบ',`<div class="form-grid"><div class="field"><label>วิชา</label><select name="subject">${opt(scope.subjects,'id',x=>`${x.code} ${x.name}`)}</select></div><div class="field"><label>ชนิด</label><select name="type"><option>practice</option><option>midterm</option><option>final</option></select></div><div class="field span2"><label>ชื่อข้อสอบ</label><input name="title" required></div><div class="field"><label>เวลา (นาที)</label><input name="duration" type="number" value="60"></div><div class="field"><label>คะแนนเต็ม</label><input name="full" type="number" value="100"></div><div class="field span2"><label>Questions JSON</label><textarea name="questions" rows="9">[{"id":"q001","type":"mcq","prompt":"ตัวเลือกที่ถูกต้องคือข้อใด","points":1,"options":["A","B","C","D"]}]</textarea></div><div class="field span2"><label>Answer Key JSON</label><textarea name="key" rows="4">{"q001":"B"}</textarea></div></div>`,async f=>{await rpc('clean_exam_save',{p_id:null,p_subject_id:f.get('subject'),p_title:f.get('title'),p_description:null,p_exam_type:f.get('type'),p_questions:JSON.parse(f.get('questions')),p_answer_key:JSON.parse(f.get('key')),p_open_at:null,p_due_at:null,p_duration_minutes:+f.get('duration'),p_attempt_limit:1,p_full_score:+f.get('full')});toast('สร้างข้อสอบแล้ว','ok');navigate('exams',false)})}
function publishExam(id){modal('Publish ข้อสอบ',`<div class="field"><label>เปิด</label><input name="open" type="datetime-local" value="${dateInput(new Date())}" required></div><div class="field"><label>ปิด</label><input name="due" type="datetime-local" required></div>`,async f=>{const d=await rpc('clean_exam_publish',{p_exam_id:id,p_open_at:new Date(f.get('open')).toISOString(),p_due_at:new Date(f.get('due')).toISOString()});toast(`Publish แล้ว ${d.assigned_count} คน`,'ok');navigate('exams',false)},'Publish')}
