async function studentExams(){const rows=await rpc('clean_my_exams');setMain(head('ข้อสอบของฉัน','ข้อสอบที่ได้รับมอบหมาย')+`<div class="course-grid">${rows.map(e=>`<div class="course-card"><div class="code">${esc(e.subject_code)}</div><h3>${esc(e.title)}</h3><p class="muted">${esc(e.exam_type)} • ${e.duration_minutes} นาที • เต็ม ${e.full_score}</p><div class="course-meta">${statusPill(e.latest_status||'ยังไม่เริ่ม')}<span class="pill">ใช้ ${e.attempts_used}/${e.attempt_limit}</span></div><div class="row" style="margin-top:12px"><button class="btn primary" data-start-exam="${e.id}">เริ่ม/ทำต่อ</button></div></div>`).join('')}</div>`);$$('[data-start-exam]').forEach(b=>b.onclick=()=>startExam(b.dataset.startExam))}
async function startExam(id){const d=await rpc('clean_exam_start',{p_exam_id:id});const a=d.attempt,e=d.exam;setMain(head(e.title,`หมดเวลา ${fmt(a.expires_at)}`,`<button class="btn light" id="backMyExam">← กลับ</button><button class="btn light" id="saveExam">บันทึก</button><button class="btn primary" id="submitExam">ส่งข้อสอบ</button>`)+`<div class="card" id="examForm">${renderQuestions(e.questions,a.answers||{})}</div>`);$('#backMyExam').onclick=()=>navigate('exams');$('#saveExam').onclick=async()=>{await rpc('clean_exam_save_answers',{p_attempt_id:a.id,p_answers:collectAnswers($('#examForm'))});toast('บันทึกคำตอบแล้ว','ok')};$('#submitExam').onclick=async()=>{if(!confirm('ยืนยันส่งข้อสอบ?'))return;const x=await rpc('clean_exam_submit',{p_attempt_id:a.id,p_answers:collectAnswers($('#examForm'))});toast(`ส่งข้อสอบแล้ว คะแนน ${x.attempt.score??'รอตรวจ'}`,'ok');navigate('exams')}}
pages.gradebook=async()=>{const scope=await rpc('clean_staff_scope');setMain(head('Gradebook','คะแนนคำนวณจาก Backend เท่านั้น')+`<div class="toolbar"><select id="gradeSubject"><option value="">เลือกวิชา</option>${opt(scope.subjects,'id',x=>`${x.code} ${x.name}`)}</select><button class="btn primary" id="loadGrade">โหลดคะแนน</button><button class="btn light" id="exportGrade" disabled>Export CSV</button></div><div id="gradeBody" class="empty">เลือกวิชาเพื่อดูคะแนน</div>`);let current=[];$('#loadGrade').onclick=async()=>{const id=$('#gradeSubject').value;if(!id)return;$('#gradeBody').innerHTML=loading();const d=await rpc('clean_gradebook',{p_subject_id:id});current=d.rows;$('#exportGrade').disabled=false;$('#gradeBody').innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>รหัส</th><th>ชื่อ</th><th>งาน</th><th>พฤติกรรม</th><th>กลางภาค</th><th>ปลายภาค</th><th>รวม</th><th>เกรด</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td>${esc(r.student_code||'')}</td><td>${esc(r.full_name)}</td><td>${r.worksheet_score}</td><td>${r.behavior_score}</td><td>${r.midterm_score}</td><td>${r.final_score}</td><td><strong>${r.total_score}</strong></td><td>${r.grade}</td></tr>`).join('')}</tbody></table></div>`};$('#exportGrade').onclick=()=>downloadCSV(current)}
function downloadCSV(rows){const cols=['student_code','full_name','worksheet_score','behavior_score','midterm_score','final_score','total_score','grade','pass_status'];const csv='\ufeff'+[cols.join(','),...rows.map(r=>cols.map(c=>`"${String(r[c]??'').replaceAll('"','""')}"`).join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='gradebook.csv';a.click();URL.revokeObjectURL(a.href)}
