async function showGroup(id){const [members,scope]=await Promise.all([rpc('clean_room_group_members',{p_group_id:id}),rpc('clean_staff_scope')]);setMain(head('รายละเอียดกลุ่มห้อง','สมาชิกและรายวิชา',`<button class="btn light" id="backGroup">← กลับ</button>${state.profile.role==='admin'?'<button class="btn primary" id="manageMembers">จัดสมาชิก</button><button class="btn light" id="bindSubject">ผูกวิชา</button>':''}`)+`<div class="table-wrap"><table class="table"><thead><tr><th>เลขที่</th><th>รหัส</th><th>ชื่อ</th></tr></thead><tbody>${members.map(x=>`<tr><td>${x.seat_number??'-'}</td><td>${esc(x.student_code||'')}</td><td>${esc(x.full_name)}</td></tr>`).join('')}</tbody></table></div>`);$('#backGroup').onclick=()=>navigate('groups');if(state.profile.role==='admin'){const master=await rpc('clean_admin_master_data');$('#manageMembers').onclick=()=>{const students=master.users.filter(x=>x.role==='student');modal('จัดสมาชิก',`<div class="stack">${students.map(s=>`<label class="choice"><input type="checkbox" name="stu" value="${s.id}" ${members.some(m=>m.student_id===s.id)?'checked':''}> ${esc(s.student_code||'')} ${esc(s.full_name)}</label>`).join('')}</div>`,async()=>{const list=$$('#modalForm [name=stu]:checked').map((x,i)=>({student_id:x.value,seat_number:i+1,active:true}));await rpc('clean_room_group_replace_members',{p_group_id:id,p_members:list});toast('อัปเดตสมาชิกแล้ว','ok');showGroup(id)})};$('#bindSubject').onclick=()=>modal('ผูกรายวิชา',`<div class="field"><label>วิชา</label><select name="subject">${opt(scope.subjects,'id',x=>`${x.code} ${x.name}`)}</select></div>`,async f=>{await rpc('clean_room_group_bind_subject',{p_group_id:id,p_subject_id:f.get('subject'),p_active:true});toast('ผูกรายวิชาแล้ว','ok')})}}
