pages.profile=async()=>{const p=await rpc('clean_my_profile');setMain(head('โปรไฟล์','ข้อมูลบัญชีใน Clean V1')+`<div class="card"><div class="form-grid"><div><strong>ชื่อ</strong><p>${esc(p.full_name)}</p></div><div><strong>บทบาท</strong><p>${esc(p.role)}</p></div><div><strong>Username</strong><p>${esc(p.username||'-')}</p></div><div><strong>รหัสนักศึกษา</strong><p>${esc(p.student_code||'-')}</p></div><div><strong>สถานะ</strong><p>${statusPill(p.active?'active':'inactive')} ${statusPill(p.approval_status)}</p></div></div></div>`)};

function appBase(){return location.origin==='null'?'https://app.test/':`${location.origin}${location.pathname}`}
async function loadExternal(urls,test){if(test())return true;for(const url of urls){try{await new Promise((resolve,reject)=>{const sc=document.createElement('script');sc.src=url;sc.async=true;sc.onload=resolve;sc.onerror=reject;document.head.appendChild(sc)});if(test())return true}catch{}}return false}
async function makeQr(el,text,size=230){
  if(!el)return false;el.innerHTML='';
  try{if(state.session?.access_token){const d=await edge('clean-qr-render',{text,size});if(d?.svg){el.innerHTML=d.svg;return true}}}catch{}
  const ok=await loadExternal(['https://cdn.jsdelivr.net/npm/qrcodejs@1.0.0/qrcode.min.js','https://unpkg.com/qrcodejs@1.0.0/qrcode.min.js'],()=>typeof window.QRCode==='function');
  if(ok){new window.QRCode(el,{text,width:size,height:size,correctLevel:window.QRCode.CorrectLevel?.M});return true}
  el.innerHTML=`<div class="error">ไม่สามารถสร้าง QR ได้ในขณะนี้ กรุณาลองใหม่</div><textarea class="answer-box" readonly>${esc(text)}</textarea>`;return false
}
function attendanceLink(token,mode){const u=new URL(appBase());u.searchParams.set('att',token);u.searchParams.set('mode',mode);return u.toString()}
function identityLink(token){const u=new URL(appBase());u.searchParams.set('profile',token);return u.toString()}
function parseAttendanceQr(raw){
  const t=String(raw||'').trim();if(!t)throw new Error('QR_EMPTY');
  try{const u=new URL(t);const token=u.searchParams.get('att');if(token)return{token,mode:u.searchParams.get('mode')||'auto'}}catch{}
  const m=t.match(/^DOCNR:ATT:([0-9a-f-]{36}):(present|late|auto)$/i);if(m)return{token:m[1],mode:m[2].toLowerCase()};
  if(/^[0-9a-f-]{36}$/i.test(t))return{token:t,mode:'auto'};
  throw new Error('QR นี้ไม่ใช่ QR เช็กชื่อของ DOC-FULL-NR')
}
async function showAttendanceQr(sessionId,mode){
  const d=await rpc('clean_attendance_qr_issue',{p_session_id:sessionId,p_mode:mode,p_ttl_minutes:10});const link=attendanceLink(d.token,mode);const label=mode==='late'?'QR เช็กชื่อสาย':'QR เข้าเรียน';
  modal(label,`<div class="qr-modal"><div id="attendanceQr" class="qr-box"></div><div class="pill ${mode==='late'?'warn':'ok'}">${mode==='late'?'บันทึกเป็น “สาย”':'บันทึกเป็น “มา”'}</div><p>หมดอายุ ${fmt(d.expires_at)}</p><p class="muted">นักศึกษาเปิด Mobile Companion แล้วสแกน QR นี้ หรือใช้กล้องของโทรศัพท์สแกนลิงก์ได้โดยตรง</p><textarea class="answer-box" readonly>${esc(link)}</textarea></div>`,async()=>{},'ปิด');
  await makeQr($('#attendanceQr'),link,260)
}
function mobileCopySetting(id,enabled){
  const def=new Date(Date.now()+7*86400000);modal('ส่งงานย้อนหลังด้วยมือถือ',`<div class="notice">เมื่อเปิด นักศึกษาที่ได้รับใบงานจะสามารถถ่ายรูปสำเนางานและส่งจากโทรศัพท์ได้</div><div class="field"><label>สถานะ</label><select name="enabled"><option value="true" ${enabled?'selected':''}>เปิดรับ</option><option value="false" ${!enabled?'selected':''}>ปิดรับ</option></select></div><div class="field"><label>รับถึง (เว้นว่าง = ไม่กำหนด)</label><input name="until" type="datetime-local" value="${enabled?'':dateInput(def)}"></div>`,async f=>{const on=f.get('enabled')==='true';const until=f.get('until');await rpc('clean_worksheet_mobile_copy_setting',{p_worksheet_id:id,p_enabled:on,p_until:on&&until?new Date(until).toISOString():null});toast(on?'เปิดรับงานย้อนหลังบนมือถือแล้ว':'ปิดรับงานย้อนหลังแล้ว','ok');navigate('worksheets',false)})
}
async function reviewMobileCopy(row){
  const files=asArr(row.files);modal(`งานย้อนหลัง • ${row.full_name}`,`<div class="notice">${esc(row.subject_code)} • ${esc(row.worksheet_title)} • ครั้งที่ ${row.attempt_no}</div><div id="mobileCopyImages" class="mobile-copy-images">${files.map((_,i)=>`<div class="copy-image loading-mini" data-img="${i}">กำลังโหลดภาพ ${i+1}...</div>`).join('')}</div><div class="field"><label>หมายเหตุของนักศึกษา</label><div class="notice">${esc(row.note||'-')}</div></div><div class="field"><label>ความเห็นผู้ตรวจ</label><textarea name="review_note"></textarea></div><button type="button" id="rejectMobileCopy" class="btn danger full">ไม่รับงาน</button>`,async f=>{await rpc('clean_mobile_copy_review',{p_submission_id:row.id,p_decision:'accepted',p_note:f.get('review_note')});toast('รับงานย้อนหลังแล้ว และส่งเข้าคิวตรวจคะแนน','ok');navigate('submissions',false)},'รับงาน');
  files.forEach(async(path,i)=>{const box=$(`[data-img="${i}"]`);try{const d=await edge('clean-mobile-file-url',{path});box.className='copy-image';box.innerHTML=`<a href="${esc(d.url)}" target="_blank" rel="noopener"><img src="${esc(d.url)}" alt="สำเนางาน ${i+1}"></a>`}catch(e){box.className='error';box.textContent=errText(e)}});
  $('#rejectMobileCopy').onclick=async()=>{const note=$('#modalForm [name=review_note]').value;try{await rpc('clean_mobile_copy_review',{p_submission_id:row.id,p_decision:'rejected',p_note:note});$('#modalRoot').innerHTML='';toast('บันทึกว่าไม่รับงานแล้ว','ok');navigate('submissions',false)}catch(e){$('#modalError').innerHTML=`<div class="error">${esc(errText(e))}</div>`}}
}
