async function processAttendanceToken(token,expectedMode='auto',fromLink=false){
  const main=$('#mobileMain');if(main)main.innerHTML=`<div class="mobile-status"><div class="spinner"></div><h2>กำลังบันทึกเช็กชื่อ...</h2></div>`;
  try{const d=await rpc('clean_attendance_qr_scan',{p_token:token,p_expected_mode:expectedMode});if(fromLink)clearMobileQuery();if(main)main.innerHTML=`<div class="mobile-status success-card"><div class="result-icon">✓</div><h1>${d.status==='late'?'เช็กชื่อสายสำเร็จ':'เข้าเรียนสำเร็จ'}</h1><p>สถานะ: <strong>${d.status==='late'?'สาย':'มา'}</strong></p>${d.already_checked?'<div class="notice">รายการนี้ถูกเช็กชื่อไว้ก่อนแล้ว ระบบไม่ได้เปลี่ยนสถานะซ้ำ</div>':''}<button class="btn primary full" id="backMobileHome">กลับหน้าหลัก</button></div>`;$('#backMobileHome')?.addEventListener('click',renderMobileHome);return d}
  catch(e){if(fromLink)clearMobileQuery();if(main)main.innerHTML=`<div class="mobile-status"><div class="result-icon bad">!</div><h2>เช็กชื่อไม่สำเร็จ</h2><div class="error">${esc(errText(e))}</div><button class="btn light full" id="backMobileHome">กลับหน้าหลัก</button></div>`;$('#backMobileHome')?.addEventListener('click',renderMobileHome);throw e}
}
function renderMobileScanner(expectedMode){
  if(state.cameraStop){try{state.cameraStop()}catch{}state.cameraStop=null}const main=$('#mobileMain');const title=expectedMode==='late'?'สแกน QR มาสาย':'สแกน QR เข้าเรียน';main.innerHTML=`<div class="mobile-page-head"><button class="back-link" id="mobileBack">←</button><div><h1>${title}</h1><p>ใช้กล้องหลังสแกน QR ที่ครูแสดง</p></div></div><div class="scanner-card"><div id="qrReader" class="qr-reader"><video id="qrVideo" playsinline muted></video><div class="scanner-placeholder">กด “เปิดกล้อง” เพื่อเริ่มสแกน</div></div><button id="startCamera" class="btn primary full">เปิดกล้องสแกน QR</button><div class="divider">หรือ</div><div class="field"><label>วางลิงก์/Token จาก QR</label><input id="manualQr" placeholder="https://.../?att=..."></div><button id="manualQrBtn" class="btn light full">ตรวจ QR ที่วาง</button><div id="scanError"></div><div class="mobile-note">ถ้ากล้องในเว็บไม่รองรับ สามารถเปิดแอปกล้องของโทรศัพท์สแกน QR ได้ ระบบจะเปิดหน้านี้และเช็กชื่อให้อัตโนมัติ</div></div>`;
  $('#mobileBack').onclick=renderMobileHome;$('#manualQrBtn').onclick=async()=>{try{const q=parseAttendanceQr($('#manualQr').value);if(expectedMode!=='auto'&&q.mode!=='auto'&&q.mode!==expectedMode)throw new Error('QR คนละประเภทกับเมนูนี้');await processAttendanceToken(q.token,expectedMode)}catch(e){$('#scanError').innerHTML=`<div class="error">${esc(errText(e))}</div>`}};$('#startCamera').onclick=()=>startQrCamera(expectedMode)
}
async function startQrCamera(expectedMode){
  const err=$('#scanError');err.innerHTML='';$('#startCamera').disabled=true;$('.scanner-placeholder')?.remove();
  const done=async raw=>{try{if(state.cameraStop){state.cameraStop();state.cameraStop=null}const q=parseAttendanceQr(raw);if(expectedMode!=='auto'&&q.mode!=='auto'&&q.mode!==expectedMode)throw new Error('QR คนละประเภทกับเมนูนี้');await processAttendanceToken(q.token,expectedMode)}catch(e){err.innerHTML=`<div class="error">${esc(errText(e))}</div>`;$('#startCamera').disabled=false}};
  try{
    if('BarcodeDetector' in window){
      const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}},audio:false});const video=$('#qrVideo');video.srcObject=stream;await video.play();const detector=new BarcodeDetector({formats:['qr_code']});let active=true;state.cameraStop=()=>{active=false;stream.getTracks().forEach(t=>t.stop())};
      const tick=async()=>{if(!active)return;try{const codes=await detector.detect(video);if(codes?.[0]?.rawValue){active=false;stream.getTracks().forEach(t=>t.stop());await done(codes[0].rawValue);return}}catch{}requestAnimationFrame(tick)};requestAnimationFrame(tick);return
    }
    const ok=await loadExternal(['https://cdn.jsdelivr.net/npm/html5-qrcode@2.3.8/html5-qrcode.min.js','https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js'],()=>typeof window.Html5Qrcode==='function');
    if(!ok)throw new Error('เบราว์เซอร์นี้ไม่รองรับตัวสแกนในเว็บ กรุณาใช้แอปกล้องของโทรศัพท์สแกน QR');
    $('#qrVideo')?.remove();const scanner=new window.Html5Qrcode('qrReader');let stopped=false;state.cameraStop=()=>{if(!stopped){stopped=true;scanner.stop().catch(()=>{})}};await scanner.start({facingMode:'environment'},{fps:10,qrbox:{width:250,height:250}},async text=>{if(stopped)return;stopped=true;await scanner.stop().catch(()=>{});await done(text)},()=>{})
  }catch(e){err.innerHTML=`<div class="error">${esc(errText(e))}</div>`;$('#startCamera').disabled=false}
}
async function renderMobileIdentity(){
  const main=$('#mobileMain');main.innerHTML=loading();try{const d=await rpc('clean_my_identity_qr',{p_rotate:false});const link=identityLink(d.token);const p=d.profile||{};main.innerHTML=`<div class="mobile-page-head"><button class="back-link" id="mobileBack">←</button><div><h1>QR ประจำตัว</h1><p>ใช้ยืนยันข้อมูลพื้นฐานของนักศึกษา</p></div></div><div class="identity-card"><div id="identityQr" class="qr-box"></div><h2>${esc(p.full_name||state.profile.full_name)}</h2><div class="student-code">${esc(p.student_code||state.profile.student_code||'-')}</div><p>${esc(p.classroom_name||'-')}</p><div class="mobile-note">QR นี้ไม่บรรจุเบอร์โทรหรืออีเมล ผู้สแกนจะเห็นเฉพาะชื่อ รหัส ห้อง และสถานะการศึกษา</div><button id="rotateIdentity" class="btn light full">ออก QR ใหม่</button></div>`;$('#mobileBack').onclick=renderMobileHome;await makeQr($('#identityQr'),link,240);$('#rotateIdentity').onclick=async()=>{if(!confirm('ออก QR ใหม่? QR เดิมจะใช้งานไม่ได้'))return;await rpc('clean_my_identity_qr',{p_rotate:true});toast('ออก QR ใหม่แล้ว','ok');renderMobileIdentity()}}
  catch(e){main.innerHTML=`<div class="error">${esc(errText(e))}</div><button class="btn light full" id="mobileBack">กลับ</button>`;$('#mobileBack').onclick=renderMobileHome}
}
async function renderMobileCopy(){
  const main=$('#mobileMain');main.innerHTML=loading();try{const rows=await rpc('clean_my_mobile_copy_targets');main.innerHTML=`<div class="mobile-page-head"><button class="back-link" id="mobileBack">←</button><div><h1>ส่งงานย้อนหลัง</h1><p>ถ่ายรูปสำเนางานสูงสุด 6 ภาพ</p></div></div>${rows.length?`<div class="mobile-form-card"><div class="field"><label>เลือกใบงาน</label><select id="copyWorksheet">${rows.map(w=>`<option value="${w.id}">${esc(w.subject_code)} • ${esc(w.title)}</option>`).join('')}</select></div><div class="mobile-note">แสดงเฉพาะใบงานที่ครูเปิดรับการส่งย้อนหลังผ่านมือถือ</div><label class="camera-pick"><span>📷</span><strong>ถ่ายรูป / เพิ่มรูป</strong><small>รองรับสูงสุด 6 รูป</small><input id="copyCamera" type="file" accept="image/*" capture="environment"></label><div id="copyFiles" class="copy-files"></div><div class="field"><label>หมายเหตุ</label><textarea id="copyNote" placeholder="เช่น ส่งย้อนหลังตามที่ครูอนุญาต"></textarea></div><button id="submitMobileCopy" class="btn primary full">ส่งสำเนางาน</button><div id="copyProgress"></div></div>`:'<div class="mobile-empty"><div class="mobile-icon">📭</div><h2>ยังไม่มีงานที่เปิดรับ</h2><p>เมื่อครูเปิด “ส่งงานย้อนหลังมือถือ” ใบงานจะปรากฏที่นี่</p></div>'}`;$('#mobileBack').onclick=renderMobileHome;if(!rows.length)return;state.mobileFiles=[];$('#copyCamera').onchange=e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;if(state.mobileFiles.length>=6){toast('เพิ่มได้สูงสุด 6 รูป','bad');return}state.mobileFiles.push(f);drawMobileFiles()};$('#submitMobileCopy').onclick=submitMobileCopy}
  catch(e){main.innerHTML=`<div class="error">${esc(errText(e))}</div><button class="btn light full" id="mobileBack">กลับ</button>`;$('#mobileBack').onclick=renderMobileHome}
}
function drawMobileFiles(){const box=$('#copyFiles');if(!box)return;box.innerHTML=state.mobileFiles.length?state.mobileFiles.map((f,i)=>`<div class="copy-file"><div><strong>ภาพ ${i+1}</strong><small>${esc(f.name)} • ${(f.size/1024/1024).toFixed(1)} MB</small></div><button class="btn danger sm" data-remove-file="${i}">ลบ</button></div>`).join(''):'<div class="empty compact">ยังไม่ได้ถ่ายรูป</div>';$$('[data-remove-file]').forEach(b=>b.onclick=()=>{state.mobileFiles.splice(+b.dataset.removeFile,1);drawMobileFiles()})}
async function prepareMobileImage(file){
  if(!String(file.type||'').startsWith('image/'))throw new Error('รองรับเฉพาะไฟล์รูปภาพ');
  if(file.size>20*1024*1024)throw new Error('รูปต้นฉบับใหญ่เกิน 20 MB');
  if(file.size<=2.5*1024*1024&&['image/jpeg','image/png','image/webp'].includes(file.type))return file;
  try{const bitmap=await createImageBitmap(file);const max=1920,scale=Math.min(1,max/Math.max(bitmap.width,bitmap.height));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(bitmap.width*scale));c.height=Math.max(1,Math.round(bitmap.height*scale));c.getContext('2d').drawImage(bitmap,0,0,c.width,c.height);bitmap.close?.();const blob=await new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(new Error('IMAGE_COMPRESS_FAILED')),'image/jpeg',.82));return new File([blob],(file.name.replace(/\.[^.]+$/,'')||'photo')+'.jpg',{type:'image/jpeg'})}catch(e){if(file.size<=12*1024*1024)return file;throw new Error('ไม่สามารถย่อรูปได้ กรุณาถ่ายรูปใหม่หรือเลือกรูปที่เล็กกว่า 12 MB')}
}
async function uploadMobileImage(file,worksheetId,index){const f=await prepareMobileImage(file);const ext=f.type==='image/png'?'png':f.type==='image/webp'?'webp':f.type==='image/heic'?'heic':f.type==='image/heif'?'heif':'jpg';const uuid=crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random().toString(16).slice(2)}`;const path=`${state.profile.id}/${worksheetId}/${Date.now()}-${index}-${uuid}.${ext}`;const encoded=path.split('/').map(encodeURIComponent).join('/');await request(`${CONFIG.supabaseUrl}/storage/v1/object/clean-mobile-submissions/${encoded}`,{method:'POST',headers:{'Content-Type':f.type||'image/jpeg','x-upsert':'false'},body:f});return path}
async function submitMobileCopy(){const btn=$('#submitMobileCopy'),progress=$('#copyProgress');if(!state.mobileFiles.length){progress.innerHTML='<div class="error">กรุณาถ่ายอย่างน้อย 1 รูป</div>';return}const worksheetId=$('#copyWorksheet').value;btn.disabled=true;try{const paths=[];for(let i=0;i<state.mobileFiles.length;i++){progress.innerHTML=`<div class="notice">กำลังอัปโหลดภาพ ${i+1}/${state.mobileFiles.length}...</div>`;paths.push(await uploadMobileImage(state.mobileFiles[i],worksheetId,i+1))}progress.innerHTML='<div class="notice">กำลังบันทึกการส่งงาน...</div>';await rpc('clean_mobile_copy_submit',{p_worksheet_id:worksheetId,p_files:paths,p_note:$('#copyNote').value});progress.innerHTML='<div class="success">ส่งสำเนางานเรียบร้อยแล้ว รอครูตรวจรับ</div>';state.mobileFiles=[];drawMobileFiles();toast('ส่งงานย้อนหลังสำเร็จ','ok')}catch(e){progress.innerHTML=`<div class="error">${esc(errText(e))}</div>`}finally{btn.disabled=false}}

let lastPhone=isPhone();window.addEventListener('resize',()=>{const now=isPhone();if(now!==lastPhone){lastPhone=now;location.reload()}});
boot();
